import{_ as o,o as a,c as n,a6 as d}from"./chunks/framework.ZMCvXf1_.js";const p=JSON.parse('{"title":"Discovering command help","description":"","frontmatter":{},"headers":[],"relativePath":"cli/help.md","filePath":"cli/help.md"}'),c={name:"cli/help.md"};function r(t,e,l,h,i,s){return a(),n("div",null,[...e[0]||(e[0]=[d(`<h1 id="discovering-command-help" tabindex="-1">Discovering command help <a class="header-anchor" href="#discovering-command-help" aria-label="Permalink to “Discovering command help”">​</a></h1><p>Every <code>noorm</code> command exposes its own help via the standard <code>--help</code> (or <code>-h</code>) flag. There is no <code>noorm help &lt;subcommand&gt;</code> form — <code>noorm</code>&#39;s CLI framework (citty) renders help natively per command, and that&#39;s the canonical surface.</p><h2 id="canonical-form" tabindex="-1">Canonical form <a class="header-anchor" href="#canonical-form" aria-label="Permalink to “Canonical form”">​</a></h2><p>Append <code>--help</code> (or the short <code>-h</code>) to any command — including multi-segment commands like <code>db create</code> or <code>change ff</code>:</p><pre><code>noorm --help
noorm db --help
noorm db create --help
noorm change ff --help
noorm sql query --help
</code></pre><p>The help output includes the usage line, every flag with its description, and a curated <code>EXAMPLES</code> block where the command author added one.</p><h2 id="why-not-noorm-help-sub" tabindex="-1">Why not <code>noorm help &lt;sub&gt;</code>? <a class="header-anchor" href="#why-not-noorm-help-sub" aria-label="Permalink to “Why not noorm help &lt;sub&gt;?”">​</a></h2><p>citty (the CLI framework <code>noorm</code> is built on) doesn&#39;t ship a re-dispatching <code>help</code> subcommand. Adding one would mean a parallel copy of every command&#39;s help text — easy to let drift. The <code>--help</code> flag is uniform, always current, and matches the convention used by <code>git</code>, <code>kubectl</code>, <code>docker</code>, and most other modern CLIs.</p><p>If you arrive from a tool like <code>npm</code>, <code>yarn</code>, or older <code>commander</code>-based CLIs that DO support <code>npm help &lt;sub&gt;</code>, just swap to the flag form:</p><pre><code># this errors with &quot;Unknown command help&quot;
noorm help db create

# this is the equivalent that works
noorm db create --help
</code></pre><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to “Related”">​</a></h2><ul><li><a href="./flags.html">Flag conventions</a> — where <code>--help</code> and other flags must be placed relative to the subcommand.</li></ul>`,12)])])}const u=o(c,[["render",r]]);export{p as __pageData,u as default};
